using System.Text.Json;
using TennoForge.Core;

internal static class EnemyChecks
{
    internal static void Run(Action<string,Action> check)
    {
        var enemies=EnemyCatalog.Load();
        EnemySelection S(string name,int level,EnemyDifficulty difficulty=EnemyDifficulty.Normal,int squad=6)=>new(enemies.Enemies.Single(e=>e.EnglishName==name).Id,level,difficulty,squad);
        EnemyStats C(string name,int level,EnemyDifficulty difficulty=EnemyDifficulty.Normal,int squad=6)=>EnemyScaling.Calculate(S(name,level,difficulty,squad));
        void Yes(bool condition){if(!condition)throw new Exception("적 설정 검증 실패");}
        void Near(double actual,double expected,double tolerance=.00001){if(Math.Abs(actual-expected)>tolerance*Math.Max(1,Math.Abs(expected)))throw new Exception($"{actual} != {expected}");}
        void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("잘못된 적 설정을 허용함");}
        check("적 자료: 고유 ID·팩션·개정·원본 해시 보존",()=>{Yes(enemies.Enemies.Length==31);Yes(enemies.Enemies.Select(e=>e.Id).Distinct().Count()==31);foreach(var e in enemies.Enemies){Yes(e.Id.StartsWith("/Lotus/")&&e.Source.Revision>0&&e.Source.Sha256.Length==64);Yes(MeleeRuleCatalog.Load().EnemyProfiles.Any(p=>p.Id==e.Faction));}});
        check("기본 레벨: 헤비 거너와 크루맨의 위키 기본 수치",()=>{var h=C("Heavy Gunner",8);Near(h.Health,300);Near(h.Armor,500);Near(h.Shields,0);var c=C("Crewman",1);Near(c.Health,90);Near(c.Shields,120);Near(c.Armor,0);});
        check("방어력 하한: 무방어 0 유지, 랜서·부처 최초 방어력 200",()=>{Near(C("Charger",1).Armor,0);Near(C("Lancer",1).Armor,200);Near(C("Butcher",1).Armor,200);Near(C("Butcher",1).BaseArmor,5);});
        check("강철의 길: 같은 표시 레벨 체력·실드 ×2.5, 방어력 추가 배수 없음",()=>{foreach(var name in new[]{"Heavy Gunner","Crewman","Charger"}){var n=C(name,200);var sp=C(name,200,EnemyDifficulty.SteelPath);Near(sp.Health,n.Health*2.5);Near(sp.Shields,n.Shields*2.5);Near(sp.Armor,n.Armor);}});
        check("레벨은 표시 레벨: 강철의 길에 100레벨을 중복 가산하지 않음",()=>{var sp=C("Lancer",1,EnemyDifficulty.SteelPath);Near(sp.Health,250);Near(sp.Armor,200);Yes(sp.Health<C("Lancer",101).Health);});
        check("빙주령: 분대원 1·3·6명은 +300·500·800%, SP 중복 적용 없음",()=>{foreach(var squad in new[]{1,3,6}){var normal=C("Crewman",999);var ice=C("Crewman",999,EnemyDifficulty.Icebind,squad);Near(ice.StatMultiplier,3+squad);Near(ice.Health,normal.Health*(3+squad));Near(ice.Shields,normal.Shields*(3+squad));Near(ice.Armor,0);}});
        check("빙주령 방어력: 위키 코드의 기본 방어력 배수 → 레벨 성장 → 2700 제한",()=>{var a=C("Heavy Gunner",999,EnemyDifficulty.Icebind);Near(a.Armor,2700);Near(a.BaseArmor,4500);Near(DamageEngine.EnemyArmorReduction(a.Armor),.9);Yes(a.UncappedArmor>a.Armor&&a.Notes.Any(n=>n.Contains("2816353"))&&!a.Notes.Any(n=>n.Contains("가정")));});
        check("성장식 전환 70·75·80: 위키 두 곡선의 smoothstep",()=>{foreach(var q in new[]{70,75,80}){var a=1+.015*Math.Pow(q,2.12);var b=1+10.7332*Math.Pow(q,.72);var t=(q-70)/10d;var expected=100*(a+(b-a)*t*t*(3-2*t));Near(C("Lancer",q+1).Health,expected);}});
        check("팩션별 성장식: 코퍼스·인페스티드·커럽티드·속삭임·테크병",()=>{foreach(var (name,c,power) in new[]{("Crewman",13.4165,.55),("Charger",16.0998,.72),("Corrupted Lancer",10.7332,.685),("Lumbering Fragment",10.7332,.5),("Techrot Matmas",15.0998,.7)}){var e=enemies.Enemies.Single(e=>e.EnglishName==name);Near(C(name,e.BaseLevel+100).Health,e.Health*(1+c*Math.Pow(100,power)));}});
        check("적 설정: 레벨·인원·자료 버전·불가능한 빙주령 팩션 거부",()=>{Reject(()=>C("Heavy Gunner",1));Reject(()=>C("Lancer",10000));Reject(()=>C("Lancer",998,EnemyDifficulty.Icebind));Reject(()=>C("Lancer",999,EnemyDifficulty.Icebind,7));Reject(()=>C("Scaldra Jaeger",999,EnemyDifficulty.Icebind));Reject(()=>EnemyScaling.Calculate(S("Lancer",200) with {DataVersion="unknown"}));});
        check("적 자동 적용: 저장 왕복·레이어·팩션·기본 방어력 및 프라이머 보존",()=>{var c=Catalog.LoadMelee();var b=new Build(c.Weapons[0].Id,new ModSlot?[8],new(Enemy:new(1,0)),c.Version,5,Melee:new(Statuses:new(){[DamageType.Viral]=3}),Encounter:new(EncounterMode.Primer));b=EnemyScaling.Apply(b,S("Crewman",200,EnemyDifficulty.SteelPath));var copy=JsonSerializer.Deserialize<Build>(JsonSerializer.Serialize(b,Catalog.Json),Catalog.Json)!;Yes(copy.EnemySelection==b.EnemySelection&&copy.Scenario==b.Scenario&&copy.Melee!.Shields>0&&copy.Melee.Faction=="Corpus"&&copy.Melee.Statuses![DamageType.Viral]==3);Yes(copy.Encounter!.BaseArmor is null);var h=EnemyScaling.Apply(copy,S("Heavy Gunner",200));Near(h.Encounter!.BaseArmor!.Value,500);Near(h.Melee!.Shields,0);Yes(h.Melee.Faction=="Grineer");});
        check("일반 적 31종 레벨 경계 7개: 유한한 양수 체력·실드·0~2700 방어력",()=>{foreach(var e in enemies.Enemies)foreach(var level in new[]{e.BaseLevel,e.BaseLevel+70,e.BaseLevel+75,e.BaseLevel+80,200,999,9999})foreach(var difficulty in new[]{EnemyDifficulty.Normal,EnemyDifficulty.SteelPath}){var s=EnemyScaling.Calculate(new(e.Id,level,difficulty));Yes(double.IsFinite(s.Health)&&s.Health>0&&double.IsFinite(s.Shields)&&s.Shields>=0&&s.Armor is >=0 and <=2700);}});
        check("엑시무스: 위키 기본 수치가 연결된 27종",()=>Yes(enemies.Enemies.Count(e=>e.SupportsEximus)==27));
        check("엑시무스: 레벨1 랜서 체력250·방어력200·오버가드12",()=>{var x=EnemyScaling.Calculate(S("Lancer",1) with {Eximus=true});Near(x.Health,250);Near(x.Armor,200);Near(x.Overguard,12);});
        check("엑시무스: 무방어 체력 계수 0.375, 실드 대상 0.25",()=>{var c=EnemyScaling.Calculate(S("Charger",1) with {Eximus=true});Near(c.Health,367.5);var s=EnemyScaling.Calculate(S("Crewman",1) with {Eximus=true});Near(s.Health,247.5);Near(s.Shields,132);});
        check("엑시무스 전용 기본값: 스커지의 일반 체력을 재사용하지 않음",()=>{var x=EnemyScaling.Calculate(S("Techrot Skuzzi",8) with{Eximus=true});Near(x.Health,302.5);Near(x.Shields,137.5);});
        check("엑시무스 체력 보정 전환: 기준 레벨 차 15·25·35·50·100",()=>{foreach(var (q,factor) in new[]{(15,1d),(25,1.25),(35,2.5),(50,4.5),(100,6d)}){var x=EnemyScaling.Calculate(S("Lancer",q+1) with {Eximus=true});Near(x.Health/C("Lancer",q+1).Health,2.5*factor);}});
        check("엑시무스 기본 레벨: 헤비 거너 추가 보정도 기본 레벨 차 기준",()=>{var x=EnemyScaling.Calculate(S("Heavy Gunner",23) with {Eximus=true});Near(x.Health/C("Heavy Gunner",23).Health,1.1);});
        check("오버가드: 기본 레벨이 다른 랜서·헤비 거너가 같은 표시 레벨에서는 동일",()=>{foreach(var level in new[]{8,45,46,48,50,51,200,999,9999})Near(EnemyScaling.Calculate(S("Lancer",level) with {Eximus=true}).Overguard,EnemyScaling.Calculate(S("Heavy Gunner",level) with {Eximus=true}).Overguard);});
        check("오버가드: 레벨46·48·51 하위·보간·상위 곡선",()=>{foreach(var level in new[]{46,48,51}){var q=level-1d;var t=Math.Clamp((q-45)/5,0,1);var a=1+.0015*Math.Pow(q,4);var b=1+260*Math.Pow(q,.9);Near(EnemyScaling.Calculate(S("Lancer",level) with {Eximus=true}).Overguard,12*(a+(b-a)*t*t*(3-2*t)));}});
        check("엑시무스 강철의 길·빙주령: 체력·실드 배수, 오버가드 불변",()=>{var n=EnemyScaling.Calculate(S("Crewman",999) with {Eximus=true});foreach(var (mode,factor) in new[]{(EnemyDifficulty.SteelPath,2.5),(EnemyDifficulty.Icebind,9d)}){var x=EnemyScaling.Calculate(S("Crewman",999,mode) with {Eximus=true});Near(x.Health,n.Health*factor);Near(x.Shields,n.Shields*factor);Near(x.Overguard,n.Overguard);}});
        check("엑시무스 레벨9999: 모든 연결 적의 유한 체력·오버가드",()=>{foreach(var e in enemies.Enemies.Where(e=>e.SupportsEximus)){var x=EnemyScaling.Calculate(new(e.Id,9999,Eximus:true));Yes(double.IsFinite(x.Health)&&x.Health>0&&double.IsFinite(x.Overguard)&&x.Overguard>0);}});
        check("엑시무스 미연결 수치 거부·이전 자료 버전 호환",()=>{Reject(()=>EnemyScaling.Calculate(S("Runner",200) with {Eximus=true}));Near(EnemyScaling.Calculate(S("Lancer",200) with {DataVersion="wiki-enemies-0.6.2"}).Health,C("Lancer",200).Health);});
        check("오버가드의 띄워짐·넘어짐 면역을 CO 종류에 반영",()=>{var c=Catalog.LoadMelee();var b=new Build(c.Weapons[0].Id,new ModSlot?[8],new(),c.Version,5,Melee:new(Overguard:12,Conditions:new(){["Lifted"]=1,["Knockdown"]=1},Statuses:new(){[DamageType.Slash]=1}));Yes(TargetStatusRules.Count(b)==1);Yes(TargetStatusRules.Count(b with{Melee=b.Melee! with{Overguard=0}})==2);});
    }
}
